Navigation & Deep Linking:
// React Navigation with deep linking
import { NavigationContainer, useNavigation } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { Linking, Platform } from 'react-native';

const Stack = createNativeStackNavigator();
const Tab = createBottomTabNavigator();

// Deep linking configuration
const linking = {
  prefixes: ['myapp://', 'https://myapp.com', 'https://*.myapp.com'],
  config: {
    screens: {
      Home: {
        screens: {
          Feed: 'feed',
          Profile: {
            path: 'profile/:userId',
            parse: { userId: Number }
          }
        }
      },
      ProductDetail: {
        path: 'product/:productId',
        parse: { productId: (id: string) => id }
      },
      Settings: 'settings',
      NotFound: '*'
    }
  },
  // Handle deep links from push notifications
  async getInitialURL() {
    const url = await Linking.getInitialURL();
    if (url != null) return url;

    // Check for notification data
    const notification = await Notifications.getInitialNotification();
    if (notification) {
      return `product/${notification.data.productId}`;
    }
    return null;
  }
};

function AppNavigator() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  return (
    <NavigationContainer linking={linking} onStateChange={(state) => {
      // Screen tracking
      const route = state.routes[state.index];
      analytics.trackScreen(route.name);
    }}>
      <Stack.Navigator screenOptions={{ headerShown: false }}>
        {isLoggedIn ? (
          <Stack.Screen name="HomeTabs" component={HomeTabs} />
        ) : (
          <Stack.Screen name="Auth" component={AuthStack} />
        )}
        {/* Shared modal screens */}
        <Stack.Group screenOptions={{ presentation: 'modal' }}>
          <Stack.Screen name="ProductDetail" component={ProductDetail} />
          <Stack.Screen name="Settings" component={Settings} />
        </Stack.Group>
      </Stack.Navigator>
    </NavigationContainer>
  );
}

React Native Animations & Gestures:
// Reanimated 3 + Gesture Handler
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withTiming,
  runOnJS,
  FadeIn,
  FadeOut,
  Layout
} from 'react-native-reanimated';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';

function SwipeableCard({ item, onSwipe }) {
  const translateX = useSharedValue(0);
  const scale = useSharedValue(1);
  const opacity = useSharedValue(1);
  const isSwiped = useSharedValue(false);

  // Pan gesture
  const panGesture = Gesture.Pan()
    .onUpdate((event) => {
      if (!isSwiped.value) {
        translateX.value = event.translationX;
        scale.value = 1 - Math.min(Math.abs(event.translationX) / 600, 0.2);
      }
    })
    .onEnd((event) => {
      const threshold = 150;
      if (Math.abs(event.translationX) > threshold) {
        // Swipe completed
        isSwiped.value = true;
        translateX.value = withSpring(
          event.translationX > 0 ? 500 : -500,
          { velocity: event.velocityX },
          () => runOnJS(onSwipe)(item.id)
        );
        opacity.value = withTiming(0);
      } else {
        // Snap back
        translateX.value = withSpring(0);
        scale.value = withSpring(1);
      }
    });

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [
      { translateX: translateX.value },
      { scale: scale.value }
    ],
    opacity: opacity.value
  }));

  return (
    <Animated.View
      entering={FadeIn.springify()}
      exiting={FadeOut.springify()}
      layout={Layout.springify()}
    >
      <GestureDetector gesture={panGesture}>
        <Animated.View style={[styles.card, animatedStyle]}>
          <Text style={styles.title}>{item.title}</Text>
          <Text>{item.description}</Text>
        </Animated.View>
      </GestureDetector>
    </Animated.View>
  );
}
